package com.txanalyzer;
import android.app.*;import android.os.*;import android.content.*;import android.media.projection.MediaProjectionManager;import android.net.Uri;import android.provider.Settings;import android.graphics.Color;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
 static final int CAPTURE=10; MediaProjectionManager manager; TextView status;
 public void onCreate(Bundle b){super.onCreate(b);manager=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(30,45,30,20);root.setBackgroundColor(Color.rgb(17,24,39));TextView title=new TextView(this);title.setText("TX MD5 Analyzer\nThống kê màn hình • Không dự đoán chắc chắn");title.setTextColor(-1);title.setTextSize(22);root.addView(title);status=new TextView(this);status.setText("Chưa bắt đầu. Không gửi ảnh ra máy chủ.");status.setTextColor(-1);root.addView(status);Button start=new Button(this);start.setText("Cấp quyền và bắt đầu phân tích");root.addView(start);start.setOnClickListener(v->start());Button stop=new Button(this);stop.setText("Dừng và đóng menu nổi");root.addView(stop);stop.setOnClickListener(v->{stopService(new Intent(this,CaptureService.class));status.setText("Đã yêu cầu dừng");});setContentView(root);if(Build.VERSION.SDK_INT>=33 && checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=getPackageManager().PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},22);}
 void start(){if(!Settings.canDrawOverlays(this)){Intent i=new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName()));startActivity(i);status.setText("Cấp quyền hiển thị, rồi quay lại bấm Bắt đầu.");return;}startActivityForResult(manager.createScreenCaptureIntent(),CAPTURE);}
 protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==CAPTURE && result==RESULT_OK && data!=null){Intent i=new Intent(this,CaptureService.class);i.putExtra("result",result);i.putExtra("data",data);startForegroundService(i);status.setText("Đã yêu cầu khởi động phân tích. Mở trò chơi để thử.");}}
}
